/* =========================================================
   JOURNALIER V74 — DOCX & OPENXML EXPORT ENGINE
   Module extrait de v74-runtime.js (Lot 3.2)
   Architecture local-first / 100% navigateur (RGPD)
   ========================================================= */

function crc32(bytes) {
  let table = crc32._table;
  if (!table) {
    table = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = (c & 1) ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
      table[n] = c >>> 0;
    }
    crc32._table = table;
  }
  let c = 0xFFFFFFFF;
  for (const b of bytes) c = table[(c ^ b) & 255] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0;
}

function u16(v) {
  return [v & 255, (v >>> 8) & 255];
}

function u32(v) {
  return [v & 255, (v >>> 8) & 255, (v >>> 16) & 255, (v >>> 24) & 255];
}

function concatBytes(parts) {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let o = 0;
  for (const p of parts) {
    out.set(p, o);
    o += p.length;
  }
  return out;
}

function xmlEsc(s) {
  if (typeof globalThis !== 'undefined' && typeof globalThis.escapeXml === 'function' && globalThis.escapeXml !== xmlEsc) {
    return globalThis.escapeXml(s);
  }
  return String(s ?? "")
    // eslint-disable-next-line no-control-regex -- Élimination des contrôles illégaux en XML 1.0 (OpenXML Word)
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function safeArray(x) {
  return Array.isArray(x) ? x : [];
}

var MAX_PIA_FILE_BYTES = 20 * 1024 * 1024;
var MAX_PIA_TEXT_BYTES = 8 * 1024 * 1024;
var MAX_PIA_ZIP_ENTRIES = 200;

var OFFICIAL_PIA_DOCX_BASE64 = '';

function getEmbeddedOfficialPIATemplateBytes() {
  if (typeof atob === 'function') {
    var binary = atob(OFFICIAL_PIA_DOCX_BASE64);
    var len = binary.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  }
  if (typeof globalThis !== 'undefined' && globalThis.Buffer && typeof globalThis.Buffer.from === 'function') {
    var buf = globalThis.Buffer.from(OFFICIAL_PIA_DOCX_BASE64, 'base64');
    return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
  }
  return null;
}

function buildZipStoreArchive(files) {
  const locals = [], centrals = [];
  let offset = 0;
  const enc = new TextEncoder();
  for (const file of files) {
    const name = enc.encode(file.name);
    const data = file.data instanceof Uint8Array ? file.data : enc.encode(file.data);
    const crc = crc32(data);
    const local = Uint8Array.from([
      ...u32(0x04034b50),
      [20, 0],
      [0, 0],
      [0, 0],
      u16(0),
      u16(0),
      u32(crc),
      u32(data.length),
      u32(data.length),
      u16(name.length),
      u16(0),
      Array.from(name),
      Array.from(data)
    ].flat());
    locals.push(local);

    const central = Uint8Array.from([
      ...u32(0x02014b50),
      [20, 0],
      [20, 0],
      [0, 0],
      [0, 0],
      u16(0),
      u16(0),
      u32(crc),
      u32(data.length),
      u32(data.length),
      u16(name.length),
      u16(0),
      u16(0),
      u16(0),
      u16(0),
      u32(0),
      u32(offset),
      Array.from(name)
    ].flat());
    centrals.push(central);
    offset += local.length;
  }

  const cd = concatBytes(centrals);
  const body = concatBytes(locals);
  const end = Uint8Array.from([
    ...u32(0x06054b50),
    u16(0),
    u16(0),
    u16(files.length),
    u16(files.length),
    u32(cd.length),
    u32(body.length),
    u16(0)
  ].flat());

  return concatBytes([body, cd, end]);
}

async function unzipEntries(buffer) {
  if (!buffer) throw new Error("Tampon d'archive non fourni.");
  const arrayBuffer = buffer instanceof ArrayBuffer
    ? buffer
    : (buffer && buffer.buffer ? buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength) : new ArrayBuffer(0));
  const bytes = new Uint8Array(arrayBuffer);
  const view = new DataView(arrayBuffer);
  const max = Math.max(0, bytes.length - 65557);
  let eocd = -1;
  for (let i = bytes.length - 22; i >= max; i--) {
    if (view.getUint32(i, true) === 0x06054b50) {
      eocd = i;
      break;
    }
  }
  if (eocd < 0) throw new Error("Archive DOCX invalide ou non lisible.");
  const count = view.getUint16(eocd + 10, true);
  const cdOffset = view.getUint32(eocd + 16, true);
  const entries = {};
  if (count > MAX_PIA_ZIP_ENTRIES) throw new Error("Le document Word contient trop d’éléments.");
  let p = cdOffset;
  let totalSize = 0;
  for (let i = 0; i < count; i++) {
    if (view.getUint32(p, true) !== 0x02014b50) throw new Error("Répertoire DOCX invalide.");
    const method = view.getUint16(p + 10, true);
    const csize = view.getUint32(p + 20, true);
    const usize = view.getUint32(p + 24, true);
    const nlen = view.getUint16(p + 28, true);
    const elen = view.getUint16(p + 30, true);
    const clen = view.getUint16(p + 32, true);
    const loff = view.getUint32(p + 42, true);
    const name = new TextDecoder().decode(bytes.slice(p + 46, p + 46 + nlen));
    const lName = view.getUint16(loff + 26, true);
    const lExtra = view.getUint16(loff + 28, true);
    const start = loff + 30 + lName + lExtra;
    const compressed = bytes.slice(start, start + csize);
    totalSize += usize;
    if (totalSize > MAX_PIA_TEXT_BYTES) throw new Error("Le document Word est trop volumineux après décompression.");
    let data;
    if (method === 0) {
      data = compressed;
    } else if (method === 8) {
      if (typeof DecompressionStream !== "function") {
        throw new Error("Ce navigateur ne permet pas de décompresser le document Word localement.");
      }
      const ds = new DecompressionStream("deflate-raw");
      data = new Uint8Array(await new Response(new Blob([compressed]).stream().pipeThrough(ds)).arrayBuffer());
      if (data.length > MAX_PIA_TEXT_BYTES) throw new Error("Le document Word est trop volumineux après décompression.");
    } else {
      throw new Error("Méthode de compression DOCX non prise en charge.");
    }
    entries[name] = data;
    p += 46 + nlen + elen + clen;
  }
  return entries;
}

function normalizeDocxLabel(s) {
  return String(s || "")
    .replace(/[\u00A0\u202F\u2000-\u200B]/g, " ")
    .replace(/[’‘ʼ´`]/g, "'")
    .replace(/\s+/g, " ")
    .replace(/[:：]\s*$/, "")
    .trim()
    .toLowerCase();
}

function extractTextFromXml(xml) {
  const parts = [];
  const re = /<w:t(?:\s[^>]*)?>([^<]*)<\/w:t>/g;
  let m;
  while ((m = re.exec(xml))) {
    parts.push(m[1]);
  }
  return parts.join("");
}

function createCellParagraphsXml(value, fontTheme = "majorHAnsi", csTheme = "majorBidi") {
  const str = String(value ?? "").trim();
  if (!str) {
    return `<w:p><w:pPr><w:rPr><w:rFonts w:asciiTheme="${fontTheme}" w:hAnsiTheme="${fontTheme}" w:cstheme="${csTheme}"/><w:sz w:val="32"/><w:szCs w:val="32"/><w:lang w:val="fr-FR"/></w:rPr></w:pPr></w:p>`;
  }
  const lines = str.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  if (!lines.length) {
    return `<w:p><w:pPr><w:rPr><w:rFonts w:asciiTheme="${fontTheme}" w:hAnsiTheme="${fontTheme}" w:cstheme="${csTheme}"/><w:sz w:val="32"/><w:szCs w:val="32"/><w:lang w:val="fr-FR"/></w:rPr></w:pPr></w:p>`;
  }
  return lines.map(line => {
    return `<w:p><w:pPr><w:rPr><w:rFonts w:asciiTheme="${fontTheme}" w:hAnsiTheme="${fontTheme}" w:cstheme="${csTheme}"/><w:sz w:val="32"/><w:szCs w:val="32"/><w:lang w:val="fr-FR"/></w:rPr></w:pPr><w:r><w:rPr><w:rFonts w:asciiTheme="${fontTheme}" w:hAnsiTheme="${fontTheme}" w:cstheme="${csTheme}"/><w:sz w:val="32"/><w:szCs w:val="32"/><w:lang w:val="fr-FR"/></w:rPr><w:t xml:space="preserve">${xmlEsc(line)}</w:t></w:r></w:p>`;
  }).join("");
}

function fillT1IdentiteTable(tblXml, docModel) {
  const isDeidentified = Boolean(docModel.deidentified);
  const ident = docModel.t1_identite || {};

  function formatT1DateNaissance(dateStr) {
    if (!dateStr || typeof dateStr !== "string") return "";
    const m = dateStr.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (m) {
      return `${m[3]}/${m[2]}/${m[1]}`;
    }
    return dateStr;
  }

  const rawDateNaissance = isDeidentified ? "" : (ident.dateNaissance || "");
  const formattedDateNaissance = isDeidentified ? "" : formatT1DateNaissance(rawDateNaissance);

  const fieldValues = {
    "nom et prénom de l'élève": isDeidentified ? "" : (ident.nom || ident.eleve || docModel.eleve || ""),
    "date de naissance": formattedDateNaissance,
    "coordonnées de l'école": isDeidentified ? "" : (ident.coordonneesEcole || ident.ecole || docModel.ecole || ""),
    "classe et option": isDeidentified ? "" : (ident.classeEtOption || ident.classe || docModel.classe || ""),
    "titulaire": isDeidentified ? "" : (ident.titulaire || ""),
    "coordonnées du cpms coopérant": isDeidentified ? "" : (ident.coordonneesCpms || ""),
    "représentant du pôle territorial": ident.representantPole || "Pôle Territorial WBE BXL",
    "coordonnées du responsable de l'élève": isDeidentified ? "" : (ident.coordonneesResponsable || ident.responsable || "")
  };

  const requiredLabels = [
    "nom et prénom de l'élève",
    "date de naissance",
    "coordonnées de l'école",
    "classe et option",
    "titulaire",
    "coordonnées du cpms coopérant",
    "représentant du pôle territorial",
    "coordonnées du responsable de l'élève"
  ];

  const foundLabels = new Set();
  const trRegex = /<w:tr(?:\s[^>]*)?>[\s\S]*?<\/w:tr>/g;
  let trMatch;
  const newRows = [];

  while ((trMatch = trRegex.exec(tblXml))) {
    const rawTr = trMatch[0];
    const trOpenMatch = rawTr.match(/^<w:tr(?:\s[^>]*)?>/);
    const trOpen = trOpenMatch ? trOpenMatch[0] : "<w:tr>";
    const trPrMatch = rawTr.match(/<w:trPr(?:\s[^>]*)?>[\s\S]*?<\/w:trPr>/);
    const trPr = trPrMatch ? trPrMatch[0] : "";

    const cells = [];
    const tcRegex = /<w:tc(?:\s[^>]*)?>[\s\S]*?<\/w:tc>/g;
    let tcMatch;
    while ((tcMatch = tcRegex.exec(rawTr))) {
      cells.push(tcMatch[0]);
    }

    if (cells.length >= 2) {
      const labelText = normalizeDocxLabel(extractTextFromXml(cells[0]));
      let matchedKey = null;
      for (const req of requiredLabels) {
        if (labelText === req || labelText.startsWith(req)) {
          matchedKey = req;
          break;
        }
      }

      if (matchedKey) {
        foundLabels.add(matchedKey);
        const val = fieldValues[matchedKey] || "";
        const cell1TcPrMatch = cells[1].match(/<w:tcPr(?:\s[^>]*)?>[\s\S]*?<\/w:tcPr>/);
        const cell1TcPr = cell1TcPrMatch ? cell1TcPrMatch[0] : '<w:tcPr><w:tcW w:w="2976" w:type="pct"/></w:tcPr>';
        const newCell1 = `<w:tc>${cell1TcPr}${createCellParagraphsXml(val, "majorHAnsi", "majorBidi")}</w:tc>`;
        const newTr = `${trOpen}${trPr}${cells[0]}${newCell1}</w:tr>`;
        newRows.push(newTr);
        continue;
      }
    }
    newRows.push(rawTr);
  }

  for (const req of requiredLabels) {
    if (!foundLabels.has(req)) {
      throw new Error("Libellé introuvable dans le modèle officiel : " + req);
    }
  }

  const tblOpenMatch = tblXml.match(/^<w:tbl(?:\s[^>]*)?>/);
  const tblOpen = tblOpenMatch ? tblOpenMatch[0] : "<w:tbl>";
  const tblPrMatch = tblXml.match(/<w:tblPr(?:\s[^>]*)?>[\s\S]*?<\/w:tblPr>/);
  const tblPr = tblPrMatch ? tblPrMatch[0] : "";
  const tblGridMatch = tblXml.match(/<w:tblGrid(?:\s[^>]*)?>[\s\S]*?<\/w:tblGrid>/);
  const tblGrid = tblGridMatch ? tblGridMatch[0] : "";

  return `${tblOpen}${tblPr}${tblGrid}${newRows.join("")}</w:tbl>`;
}

function fillT2AspectsTable(tblXml, docModel) {
  const aspectsList = [
    { key: "physique et psychomoteur" },
    { key: "lié à l'autonomie" },
    { key: "comportemental et affectif" },
    { key: "communication" },
    { key: "cognitif (pédagogique)" }
  ];

  const modelAspects = safeArray(docModel.t2_aspects);
  const getAspectData = (key) => {
    const entry = modelAspects.find(a => normalizeDocxLabel(a.aspect || a.domaine || a.name || "") === key);
    return {
      ressources: entry?.ressources || "",
      difficultes: entry?.difficultes || "",
      objectifs: entry?.objectifs || entry?.objectifsPoursuivre || ""
    };
  };

  const foundLabels = new Set();
  const trRegex = /<w:tr(?:\s[^>]*)?>[\s\S]*?<\/w:tr>/g;
  let trMatch;
  const newRows = [];

  while ((trMatch = trRegex.exec(tblXml))) {
    const rawTr = trMatch[0];
    const trOpenMatch = rawTr.match(/^<w:tr(?:\s[^>]*)?>/);
    const trOpen = trOpenMatch ? trOpenMatch[0] : "<w:tr>";
    const trPrMatch = rawTr.match(/<w:trPr(?:\s[^>]*)?>[\s\S]*?<\/w:trPr>/);
    const trPr = trPrMatch ? trPrMatch[0] : "";

    const cells = [];
    const tcRegex = /<w:tc(?:\s[^>]*)?>[\s\S]*?<\/w:tc>/g;
    let tcMatch;
    while ((tcMatch = tcRegex.exec(rawTr))) {
      cells.push(tcMatch[0]);
    }

    if (cells.length >= 4) {
      const labelText = normalizeDocxLabel(extractTextFromXml(cells[0]));
      let matchedKey = null;
      for (const asp of aspectsList) {
        if (labelText === asp.key || labelText.startsWith(asp.key)) {
          matchedKey = asp.key;
          break;
        }
      }

      if (matchedKey) {
        foundLabels.add(matchedKey);
        const data = getAspectData(matchedKey);

        const getTcPr = (cell) => {
          const m = cell.match(/<w:tcPr(?:\s[^>]*)?>[\s\S]*?<\/w:tcPr>/);
          return m ? m[0] : '<w:tcPr><w:tcW w:w="1152" w:type="pct"/><w:vAlign w:val="center"/></w:tcPr>';
        };

        const newCell1 = `<w:tc>${getTcPr(cells[1])}${createCellParagraphsXml(data.ressources, "majorHAnsi", "majorHAnsi")}</w:tc>`;
        const newCell2 = `<w:tc>${getTcPr(cells[2])}${createCellParagraphsXml(data.difficultes, "majorHAnsi", "majorHAnsi")}</w:tc>`;
        const newCell3 = `<w:tc>${getTcPr(cells[3])}${createCellParagraphsXml(data.objectifs, "majorHAnsi", "majorHAnsi")}</w:tc>`;

        const newTr = `${trOpen}${trPr}${cells[0]}${newCell1}${newCell2}${newCell3}</w:tr>`;
        newRows.push(newTr);
        continue;
      }
    }
    newRows.push(rawTr);
  }

  for (const asp of aspectsList) {
    if (!foundLabels.has(asp.key)) {
      throw new Error("Libellé introuvable dans le modèle officiel : " + asp.key);
    }
  }

  const tblOpenMatch = tblXml.match(/^<w:tbl(?:\s[^>]*)?>/);
  const tblOpen = tblOpenMatch ? tblOpenMatch[0] : "<w:tbl>";
  const tblPrMatch = tblXml.match(/<w:tblPr(?:\s[^>]*)?>[\s\S]*?<\/w:tblPr>/);
  const tblPr = tblPrMatch ? tblPrMatch[0] : "";
  const tblGridMatch = tblXml.match(/<w:tblGrid(?:\s[^>]*)?>[\s\S]*?<\/w:tblGrid>/);
  const tblGrid = tblGridMatch ? tblGridMatch[0] : "";

  return `${tblOpen}${tblPr}${tblGrid}${newRows.join("")}</w:tbl>`;
}

function fillDocxTables(docXml, docModel) {
  const tblRegex = /<w:tbl(?:\s[^>]*)?>[\s\S]*?<\/w:tbl>/g;
  let match;
  const tables = [];
  while ((match = tblRegex.exec(docXml))) {
    tables.push({
      rawTbl: match[0],
      index: match.index
    });
  }

  if (tables.length < 2) {
    throw new Error("Le document Word ne contient pas les tableaux requis du PIA.");
  }

  let t1Entry = null;
  let t2Entry = null;

  for (const t of tables) {
    const textSample = normalizeDocxLabel(extractTextFromXml(t.rawTbl));
    if (!t1Entry && (textSample.includes("nom et prenom de l'eleve") || textSample.includes("nom et prénom de l'élève"))) {
      t1Entry = t;
    } else if (!t2Entry && textSample.includes("aspect") && (textSample.includes("ressources") || textSample.includes("difficult"))) {
      t2Entry = t;
    }
  }

  if (!t1Entry) {
    throw new Error("Tableau T1 (Identité) introuvable dans le document Word.");
  }
  if (!t2Entry) {
    throw new Error("Tableau T2 (5 aspects) introuvable dans le document Word.");
  }

  const newT1 = fillT1IdentiteTable(t1Entry.rawTbl, docModel);
  const newT2 = fillT2AspectsTable(t2Entry.rawTbl, docModel);

  let updatedXml = docXml.replace(t1Entry.rawTbl, newT1);
  updatedXml = updatedXml.replace(t2Entry.rawTbl, newT2);

  if (typeof globalThis !== "undefined" && globalThis.JournalierDocxPv && typeof globalThis.JournalierDocxPv.fillOfficialPIADocxPvAndAmenagements === "function") {
    updatedXml = globalThis.JournalierDocxPv.fillOfficialPIADocxPvAndAmenagements(updatedXml, docModel);
  }

  return updatedXml;
}

async function fillOfficialPIADocx(docModel, templateBuffer) {
  if (!docModel) throw new Error("Modèle documentaire PIA absent.");
  let buf = templateBuffer;
  if (!buf) {
    if (typeof globalThis !== "undefined" && globalThis.__piaOfficialTemplateBuffer) {
      buf = globalThis.__piaOfficialTemplateBuffer;
    } else if (typeof getEmbeddedOfficialPIATemplateBytes === "function") {
      buf = getEmbeddedOfficialPIATemplateBytes();
    } else if (typeof globalThis !== "undefined" && globalThis.fs && typeof globalThis.fs.readFile === "function") {
      try {
        buf = await globalThis.fs.readFile("public/modeles/PIA_modele_officiel_2025-09-11.docx");
      } catch (_) {
        // Ignorer si échec de lecture directe
      }
    } else if (typeof globalThis !== "undefined" && globalThis.process && globalThis.process.versions && globalThis.process.versions.node) {
      try {
        const fs = await import("node:fs/promises");
        const path = await import("node:path");
        const cwd = typeof globalThis.process.cwd === "function" ? globalThis.process.cwd() : ".";
        const candidatePaths = [
          path.resolve(cwd, "public/modeles/PIA_modele_officiel_2025-09-11.docx"),
          path.resolve(cwd, "dist/modeles/PIA_modele_officiel_2025-09-11.docx")
        ];
        for (const p of candidatePaths) {
          try {
            buf = await fs.readFile(p);
            break;
          } catch (_) {
            // Ignorer et essayer le chemin suivant
          }
        }
      } catch (_) {
        // Ignorer et se replier sur fetch
      }
    } else if (typeof fetch === "function") {
      const candidateUrls = [
        "/modeles/PIA_modele_officiel_2025-09-11.docx",
        "./modeles/PIA_modele_officiel_2025-09-11.docx"
      ];
      for (const url of candidateUrls) {
        try {
          const res = await fetch(url);
          if (res.ok) {
            const ctype = String(res.headers.get("content-type") || "");
            if (ctype.includes("text/html")) {
              // Interstitiel Cloud Run ou page HTML détectée : repli mémoire
              if (typeof globalThis !== "undefined" && typeof globalThis.getEmbeddedOfficialPIATemplateBytes === "function") {
                buf = globalThis.getEmbeddedOfficialPIATemplateBytes();
              }
              break;
            }
            buf = await res.arrayBuffer();
            break;
          }
        } catch (_) {
          // Ignorer et essayer l'URL suivante
        }
      }
    }

    if (!buf && typeof globalThis !== "undefined" && typeof globalThis.getEmbeddedOfficialPIATemplateBytes === "function") {
      buf = globalThis.getEmbeddedOfficialPIATemplateBytes();
    }
  }

  if (!buf) {
    throw new Error("Impossible de charger le modèle officiel PIA (.docx) depuis public/modeles/.");
  }

  const entries = await unzipEntries(buf);
  if (!entries["word/document.xml"]) {
    throw new Error("L'archive Word ne contient pas de document.xml valide.");
  }

  const dec = new TextDecoder("utf-8");
  let docXml = dec.decode(entries["word/document.xml"]);

  // Année scolaire dans les en-têtes
  const schoolYear = String(docModel.headerYear || docModel.schoolYear || (() => { const d = new Date(), y = d.getMonth() >= 7 ? d.getFullYear() : d.getFullYear() - 1; return `${y}-${y + 1}`; })()).trim();
  if (entries["word/header1.xml"]) {
    let h1 = dec.decode(entries["word/header1.xml"]);
    h1 = h1.replace(/<w:t(?:\s[^>]*)?>[\s\S]*?<\/w:t>/g, `<w:t>${xmlEsc(schoolYear)}</w:t>`);
    entries["word/header1.xml"] = h1;
  }
  if (entries["word/header2.xml"]) {
    let h2 = dec.decode(entries["word/header2.xml"]);
    h2 = h2.replace(/<w:t(?:\s[^>]*)?>\s*\d{4}\s*-\s*\d{4}\s*<\/w:t>/g, `<w:t>${xmlEsc(schoolYear)}</w:t>`);
    entries["word/header2.xml"] = h2;
  }

  // Métadonnées neutralisées dans docProps/core.xml
  const metaAuthor = String(docModel.metaAuthor || "Pôle Territorial WBE BXL").trim();
  if (entries["docProps/core.xml"]) {
    let core = dec.decode(entries["docProps/core.xml"]);
    const nowIso = new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
    core = core.replace(/<dc:creator>[\s\S]*?<\/dc:creator>/g, `<dc:creator>${xmlEsc(metaAuthor)}</dc:creator>`);
    core = core.replace(/<cp:lastModifiedBy>[\s\S]*?<\/cp:lastModifiedBy>/g, `<cp:lastModifiedBy>${xmlEsc(metaAuthor)}</cp:lastModifiedBy>`);
    core = core.replace(/<dcterms:modified(?:\s[^>]*)?>[\s\S]*?<\/dcterms:modified>/g, `<dcterms:modified xsi:type="dcterms:W3CDTF">${nowIso}</dcterms:modified>`);
    entries["docProps/core.xml"] = core;
  }

  // Remplissage des tables dans word/document.xml
  docXml = fillDocxTables(docXml, docModel);
  entries["word/document.xml"] = docXml;

  // Réempaquetage de toutes les entrées
  const fileEntries = Object.entries(entries).map(([name, data]) => ({ name, data }));
  return buildZipStoreArchive(fileEntries);
}

var DOC_H1_SET = new Set([
  "Continuité avec le PIA précédent",
  "Physique et psychomoteur",
  "Lié à l’autonomie",
  "Comportemental et affectif",
  "Communication",
  "Cognitif (pédagogique)",
  "Objectifs visés pour la période et critères d’évaluation",
  "Ressources / moyens complémentaires et aménagements P/O/M",
  "Réunion de décembre",
  "Réunion de fin d’année",
  "Points récurrents",
  "Points variables",
  "Adaptations",
  "Transfert",
  "Suites Q6",
  "Points à discuter"
]);

var DOC_H2_SET = new Set([
  "Ressources",
  "Difficultés",
  "Objectifs à poursuivre",
  "Critères d’évaluation",
  "Moyens / adaptations",
  "Évolution documentée",
  "Objectifs existants / à réévaluer :",
  "Objectifs validés :",
  "Propositions d’objectifs encore à examiner (non validées) :",
  "Propositions écartées / non retenues lors de l’examen :",
  "Participants :",
  "Retours des participants :",
  "Bilan d’évaluation des objectifs :",
  "Objectifs maintenus / reconduits :",
  "Perspectives pour la suite :"
]);

function classifyDocumentLine(line, index) {
  const trimmed = String(line || "").trim();
  if (!trimmed) return "empty";
  if (index === 0) return "title";
  if (DOC_H1_SET.has(trimmed) || /^\d{1,2}\.\s+\S/.test(trimmed)) return "h1";
  if (DOC_H2_SET.has(trimmed) || /^\d{4}-\d{2}-\d{2}\s+—\s+/.test(trimmed)) return "h2";
  if (/^[•●▪-]\s+/.test(trimmed)) return "bullet";
  if (/^[A-ZÀÂÄÉÈÊËÎÏÔÖÙÛÜÇ][^:]{1,48}\s:\s+\S/.test(trimmed)) return "kv";
  return "body";
}

function formatDocxParagraph(text, opts = {}) {
  const trimmed = String(text ?? "").trim();
  if (!trimmed) {
    return `<w:p><w:pPr><w:spacing w:before="0" w:after="${opts.afterEmpty || 60}"/></w:pPr></w:p>`;
  }
  const before = opts.before ?? 40;
  const after = opts.after ?? 60;
  const color = opts.color || "1F2937";
  const sz = opts.sz || 20;
  const bold = opts.bold ? "<w:b/>" : "";
  const italic = opts.italic ? "<w:i/>" : "";
  const align = opts.align ? `<w:jc w:val="${opts.align}"/>` : "";
  const indent = opts.indentLeft ? `<w:ind w:left="${opts.indentLeft}" ${opts.hanging ? `w:hanging="${opts.hanging}"` : ""}/>` : "";
  const pStyle = opts.style ? `<w:pStyle w:val="${opts.style}"/>` : "";
  const borderBottom = opts.borderBottomColor ? `<w:pBdr><w:bottom w:val="single" w:sz="${opts.borderBottomSz || 8}" w:space="4" w:color="${opts.borderBottomColor}"/></w:pBdr>` : "";
  const shading = opts.fill ? `<w:shd w:val="clear" w:color="auto" w:fill="${opts.fill}"/>` : "";

  if (opts.kvSplit && trimmed.includes(" : ") && !trimmed.startsWith("•")) {
    const sepIdx = trimmed.indexOf(" : ");
    const labelPart = trimmed.slice(0, sepIdx + 3);
    const valuePart = trimmed.slice(sepIdx + 3);
    return `<w:p><w:pPr>${pStyle}${align}${indent}${borderBottom}${shading}<w:spacing w:before="${before}" w:after="${after}"/></w:pPr><w:r><w:rPr><w:b/><w:color w:val="1E293B"/><w:sz w:val="${sz}"/><w:szCs w:val="${sz}"/></w:rPr><w:t xml:space="preserve">${xmlEsc(labelPart)}</w:t></w:r><w:r><w:rPr><w:color w:val="${color}"/><w:sz w:val="${sz}"/><w:szCs w:val="${sz}"/></w:rPr><w:t xml:space="preserve">${xmlEsc(valuePart)}</w:t></w:r></w:p>`;
  }

  return `<w:p><w:pPr>${pStyle}${align}${indent}${borderBottom}${shading}<w:spacing w:before="${before}" w:after="${after}"/></w:pPr><w:r><w:rPr>${bold}${italic}<w:color w:val="${color}"/><w:sz w:val="${sz}"/><w:szCs w:val="${sz}"/></w:rPr><w:t xml:space="preserve">${xmlEsc(trimmed)}</w:t></w:r></w:p>`;
}

function formatDocxTable(tableSpec) {
  const totalWidth = 9638; // Largeur utile A4 en DXA
  const colWidthsPct = safeArray(tableSpec.colWidths);
  const colCount = Math.max(1, (tableSpec.headers || tableSpec.rows?.[0] || []).length);
  const colWidthsDxa = Array.from({ length: colCount }, (_, i) => {
    const pct = colWidthsPct[i] || (100 / colCount);
    return Math.round((pct / 100) * totalWidth);
  });
  const gridCols = colWidthsDxa.map(w => `<w:gridCol w:w="${w}"/>`).join("");
  const borderColor = tableSpec.borderColor || "CBD5E1";
  const headerFill = tableSpec.headerFill || "1E3A8A";
  const headerColor = tableSpec.headerColor || "FFFFFF";

  let rowsXml = "";
  if (safeArray(tableSpec.headers).length) {
    const headerCells = tableSpec.headers.map((h, colIdx) => {
      const w = colWidthsDxa[colIdx] || Math.round(totalWidth / colCount);
      const align = (colWidthsPct[colIdx] && colWidthsPct[colIdx] <= 10) ? "center" : "left";
      return `<w:tc><w:tcPr><w:tcW w:w="${w}" w:type="dxa"/><w:shd w:val="clear" w:color="auto" w:fill="${headerFill}"/><w:tcMar><w:top w:w="90" w:type="dxa"/><w:bottom w:w="90" w:type="dxa"/><w:left w:w="120" w:type="dxa"/><w:right w:w="120" w:type="dxa"/></w:tcMar><w:vAlign w:val="center"/></w:tcPr>${formatDocxParagraph(String(h || ""), { bold: true, color: headerColor, sz: 19, before: 20, after: 20, align })}</w:tc>`;
    }).join("");
    rowsXml += `<w:tr><w:trPr><w:tblHeader/></w:trPr>${headerCells}</w:tr>`;
  }

  safeArray(tableSpec.rows).forEach((row, rowIdx) => {
    const zebraFill = rowIdx % 2 === 1 ? (tableSpec.zebraFill || "F8FAFC") : "FFFFFF";
    const cells = safeArray(row).map((cell, colIdx) => {
      const w = colWidthsDxa[colIdx] || Math.round(totalWidth / colCount);
      const isShortCol = colWidthsPct[colIdx] && colWidthsPct[colIdx] <= 10;
      const isFirstCol = colIdx === 0;
      const cellFill = isFirstCol ? (tableSpec.firstColFill || zebraFill) : zebraFill;
      const isArrayCell = cell && typeof cell === "object" && typeof cell.length === "number";
      const items = isArrayCell ? safeArray(cell).filter(Boolean) : [String(cell ?? "")];
      const paras = items.length
        ? items.map(item => {
            const str = String(item ?? "").trim();
            const prefix = (items.length > 1 && !isFirstCol && !isShortCol && !/^[•●▪-]/.test(str)) ? `• ${str}` : str;
            return formatDocxParagraph(prefix, {
              bold: Boolean(isFirstCol || isShortCol),
              color: isFirstCol ? "1E293B" : "1F2937",
              sz: 19,
              before: 25,
              after: 35,
              align: isShortCol ? "center" : "left",
              kvSplit: !isFirstCol && !isShortCol
            });
          }).join("")
        : formatDocxParagraph("", { afterEmpty: 20 });
      return `<w:tc><w:tcPr><w:tcW w:w="${w}" w:type="dxa"/><w:shd w:val="clear" w:color="auto" w:fill="${cellFill}"/><w:tcMar><w:top w:w="80" w:type="dxa"/><w:bottom w:w="80" w:type="dxa"/><w:left w:w="120" w:type="dxa"/><w:right w:w="120" w:type="dxa"/></w:tcMar><w:vAlign w:val="top"/></w:tcPr>${paras}</w:tc>`;
    }).join("");
    rowsXml += `<w:tr>${cells}</w:tr>`;
  });

  const titleXml = tableSpec.title ? formatDocxParagraph(tableSpec.title, { style: "Heading2", bold: true, color: "1E3A8A", sz: 21, before: 160, after: 60 }) : "";
  return `${titleXml}<w:tbl><w:tblPr><w:tblW w:w="${totalWidth}" w:type="dxa"/><w:tblBorders><w:top w:val="single" w:sz="6" w:space="0" w:color="${borderColor}"/><w:left w:val="single" w:sz="6" w:space="0" w:color="${borderColor}"/><w:bottom w:val="single" w:sz="6" w:space="0" w:color="${borderColor}"/><w:right w:val="single" w:sz="6" w:space="0" w:color="${borderColor}"/><w:insideH w:val="single" w:sz="4" w:space="0" w:color="E2E8F0"/><w:insideV w:val="single" w:sz="4" w:space="0" w:color="E2E8F0"/></w:tblBorders><w:tblLook w:val="04A0" w:firstRow="1" w:lastRow="0" w:firstColumn="1" w:lastColumn="0" w:noHBand="0" w:noVBand="1"/></w:tblPr><w:tblGrid>${gridCols}</w:tblGrid>${rowsXml}</w:tbl>${formatDocxParagraph("", { afterEmpty: 80 })}`;
}

function buildDocxModelArchive(model) {
  const bodyParts = [];
  for (const block of safeArray(model.blocks)) {
    if (block.type === "header_banner") {
      bodyParts.push(formatDocxParagraph(block.kicker || "PLAN INDIVIDUEL D’APPRENTISSAGE", { bold: true, color: "1D4ED8", sz: 17, before: 0, after: 30 }));
      bodyParts.push(formatDocxParagraph(block.title || "PIA annuel", { style: "Title", bold: true, color: "0F172A", sz: 30, before: 0, after: 60, borderBottomColor: "1D4ED8", borderBottomSz: 12 }));
      bodyParts.push(formatDocxParagraph(`${block.subtitle || ""} · Statut : ${block.statusBadge || ""}`, { bold: true, color: "334155", sz: 20, before: 20, after: 100 }));
      if (safeArray(block.metaRows).length) {
        bodyParts.push(formatDocxTable({
          colWidths: [18, 32, 20, 30],
          borderColor: "BFDBFE",
          firstColFill: "EFF6FF",
          zebraFill: "F8FAFC",
          rows: block.metaRows
        }));
      }
      continue;
    }
    if (block.type === "callout") {
      const fill = block.tone === "warning" ? "FFFBEB" : (block.tone === "info" ? "EFF6FF" : "F8FAFC");
      const border = block.tone === "warning" ? "F59E0B" : (block.tone === "info" ? "2563EB" : "CBD5E1");
      const lines = safeArray(block.lines);
      bodyParts.push(formatDocxTable({
        colWidths: [100],
        borderColor: border,
        firstColFill: fill,
        rows: [[[block.title ? `${block.title}` : "", ...lines].filter(Boolean)]]
      }));
      continue;
    }
    if (block.type === "kpi_grid") {
      const items = safeArray(block.items);
      if (items.length) {
        bodyParts.push(formatDocxTable({
          colWidths: items.map(() => Math.floor(100 / items.length)),
          headerFill: "EFF6FF",
          headerColor: "1E3A8A",
          headers: items.map(it => it.label),
          rows: [items.map(it => `${it.value} (${it.sub || ""})`)]
        }));
      }
      continue;
    }
    if (block.type === "section_title") {
      const label = block.number ? `${block.number}. ${block.title}` : block.title;
      bodyParts.push(formatDocxParagraph(label, { style: "Heading1", bold: true, color: "1E3A8A", sz: 24, before: 220, after: 90, borderBottomColor: "DBE3EF", borderBottomSz: 6 }));
      continue;
    }
    if (block.type === "table") {
      bodyParts.push(formatDocxTable(block));
      continue;
    }
  }

  const documentXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${bodyParts.join("")}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="992" w:right="1134" w:bottom="992" w:left="1134"/></w:sectPr></w:body></w:document>`;
  const rels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`;
  const types = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`;
  const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Aptos" w:hAnsi="Aptos"/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr></w:rPrDefault></w:docDefaults><w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:rPr><w:b/><w:sz w:val="30"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:rPr><w:b/><w:color w:val="1E3A8A"/><w:sz w:val="24"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="heading 2"/><w:rPr><w:b/><w:color w:val="334155"/><w:sz w:val="21"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="ListParagraph"><w:name w:val="List Paragraph"/></w:style></w:styles>`;

  return buildZipStoreArchive([
    { name: "[Content_Types].xml", data: types },
    { name: "_rels/.rels", data: rels },
    { name: "word/document.xml", data: documentXml },
    { name: "word/styles.xml", data: styles }
  ]);
}

function generateDocxDocument(linesOrModel, customBuilder) {
  if (linesOrModel && typeof linesOrModel === "object" && typeof linesOrModel.length !== "number") {
    const builder = customBuilder || globalThis.JournalierV74?.buildPIADocumentModel || globalThis.buildPIADocumentModel;
    const model = linesOrModel.isPIADocumentModel
      ? linesOrModel
      : (typeof builder === "function" ? builder(linesOrModel, linesOrModel.type === "PIA_MODELE_DEIDENTIFIE") : linesOrModel);
    return buildDocxModelArchive(model);
  }

  const lines = safeArray(linesOrModel);
  let firstNonEmptySeen = false;
  const paragraphs = lines.map(rawLine => {
    const line = String(rawLine ?? "");
    const trimmed = line.trim();
    if (!trimmed) {
      return `<w:p><w:pPr><w:spacing w:before="0" w:after="80"/></w:pPr></w:p>`;
    }
    const logicalIdx = firstNonEmptySeen ? 1 : 0;
    firstNonEmptySeen = true;
    const kind = classifyDocumentLine(trimmed, logicalIdx);
    if (kind === "title") {
      return `<w:p><w:pPr><w:pStyle w:val="Title"/><w:spacing w:before="0" w:after="180"/><w:pBdr><w:bottom w:val="single" w:sz="12" w:space="6" w:color="1D4ED8"/></w:pBdr></w:pPr><w:r><w:rPr><w:b/><w:color w:val="172033"/><w:sz w:val="32"/><w:szCs w:val="32"/></w:rPr><w:t xml:space="preserve">${xmlEsc(trimmed)}</w:t></w:r></w:p>`;
    }
    if (kind === "h1") {
      return `<w:p><w:pPr><w:pStyle w:val="Heading1"/><w:spacing w:before="240" w:after="100"/><w:pBdr><w:bottom w:val="single" w:sz="6" w:space="4" w:color="DBE3EF"/></w:pBdr></w:pPr><w:r><w:rPr><w:b/><w:color w:val="1D4ED8"/><w:sz w:val="24"/><w:szCs w:val="24"/></w:rPr><w:t xml:space="preserve">${xmlEsc(trimmed)}</w:t></w:r></w:p>`;
    }
    if (kind === "h2") {
      return `<w:p><w:pPr><w:pStyle w:val="Heading2"/><w:spacing w:before="160" w:after="60"/></w:pPr><w:r><w:rPr><w:b/><w:color w:val="334155"/><w:sz w:val="21"/><w:szCs w:val="21"/></w:rPr><w:t xml:space="preserve">${xmlEsc(trimmed)}</w:t></w:r></w:p>`;
    }
    if (kind === "bullet") {
      return `<w:p><w:pPr><w:pStyle w:val="ListParagraph"/><w:ind w:left="360" w:hanging="180"/><w:spacing w:before="40" w:after="60"/></w:pPr><w:r><w:rPr><w:color w:val="1F2937"/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr><w:t xml:space="preserve">${xmlEsc(trimmed)}</w:t></w:r></w:p>`;
    }
    if (kind === "kv") {
      const sepIdx = trimmed.indexOf(" : ");
      if (sepIdx > 0) {
        const labelPart = trimmed.slice(0, sepIdx + 3);
        const valuePart = trimmed.slice(sepIdx + 3);
        return `<w:p><w:pPr><w:spacing w:before="40" w:after="60"/></w:pPr><w:r><w:rPr><w:b/><w:color w:val="1E293B"/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr><w:t xml:space="preserve">${xmlEsc(labelPart)}</w:t></w:r><w:r><w:rPr><w:color w:val="334155"/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr><w:t xml:space="preserve">${xmlEsc(valuePart)}</w:t></w:r></w:p>`;
      }
    }
    return `<w:p><w:pPr><w:spacing w:before="40" w:after="80"/></w:pPr><w:r><w:rPr><w:color w:val="1F2937"/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr><w:t xml:space="preserve">${xmlEsc(trimmed)}</w:t></w:r></w:p>`;
  }).join("");

  const documentXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${paragraphs}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134"/></w:sectPr></w:body></w:document>`;
  const rels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`;
  const types = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`;
  const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Aptos" w:hAnsi="Aptos"/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr></w:rPrDefault></w:docDefaults><w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:rPr><w:b/><w:sz w:val="32"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:rPr><w:b/><w:color w:val="1D4ED8"/><w:sz w:val="24"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="heading 2"/><w:rPr><w:b/><w:color w:val="334155"/><w:sz w:val="21"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="ListParagraph"><w:name w:val="List Paragraph"/></w:style></w:styles>`;

  return buildZipStoreArchive([
    { name: "[Content_Types].xml", data: types },
    { name: "_rels/.rels", data: rels },
    { name: "word/document.xml", data: documentXml },
    { name: "word/styles.xml", data: styles }
  ]);
}

